import { ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, EventEmitter, HostListener, inject, Input, OnDestroy, OnInit, Output, ViewChild, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatTooltipModule } from '@angular/material/tooltip';
import { issueListRes } from '../../../rt/interfaces/issue.interface';

export interface QFactRapidPopupSaveInput {
  note: string;
  useHighlightedText: boolean;
}

export interface QFactRapidPopupSaveResult {
  ok: boolean;
}

export type QFactRapidPopupSaveFn =
  (input: QFactRapidPopupSaveInput) => Promise<QFactRapidPopupSaveResult>;

/** Compact popup for the QFact + Note rapid flow.
 *
 *  Spec (per UX brief):
 *   - The QFact is *already saved* by the host before this popup mounts —
 *     this popup is purely an optional note capture surface.
 *   - There is no Create button. The note auto-saves on textarea blur
 *     when non-empty. Empty note → nothing is sent.
 *   - "✔ Saved" indicator appears subtly after a successful note save.
 *   - Click outside / Escape / × closes the popup; closing without typing
 *     does *not* fail the QFact (it's already persisted).
 *   - Only one popup is shown at a time; the host enforces this by
 *     toggling its `show` flag false → true on every new selection.
 */
@Component({
  selector: 'qfact-rapid-popup',
  standalone: true,
  imports: [CommonModule, FormsModule, MatCheckboxModule, MatTooltipModule],
  templateUrl: './qfact-rapid-popup.component.html',
  styleUrl: './qfact-rapid-popup.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QFactRapidPopupComponent implements OnInit, OnDestroy {
  @Input({ required: true }) selectedIssues: issueListRes[] = [];
  /** Highlighted text shown in the note when the user ticks
   *  "Use highlighted text in note (editable)". Hosts pass the joined
   *  selection text from their own temp-annotation state — the popup
   *  is intentionally agnostic to how that state is shaped (PDF
   *  tempAnnots vs RT feedAnnotations). */
  @Input() highlightText: string = '';
  /** Pre-tick the "Use highlighted text" checkbox and seed the note
   *  with `highlightText` when the user came in via "Include selected
   *  text + note". The user can freely edit afterwards. */
  @Input() includeText: boolean = false;
  /** Caller-provided note save handler. Invoked once on textarea blur
   *  when the note is non-empty and the current value differs from the
   *  last saved value. Lets the same popup serve PDF (factService) and
   *  RT (rtfactService) without leaking either service into the popup. */
  @Input({ required: true }) saveNoteFn!: QFactRapidPopupSaveFn;
  /** Anchor convention:
   *   - `x` is where the popup attaches horizontally (with a small gap
   *     already baked in by the caller).
   *   - `y` is the vertical centre of the highlight.
   *   - `side` chooses which edge of the popup attaches at `x`:
   *       'right' (default) → popup's LEFT edge sits at x (popup extends rightward)
   *       'left'            → popup's RIGHT edge sits at x (popup extends leftward)
   *     This lets double-page PDF mode anchor the popup in the gap
   *     *between* the two pages: a left-page highlight uses 'right'
   *     so the popup sits to the right of that page; a right-page
   *     highlight uses 'left' so the popup sits to the left of it.
   */
  @Input() anchor: { x: number; y: number; side?: 'left' | 'right' } = { x: 0, y: 0 };

  /** Fired when the popup is dismissed (×, click-outside, Escape).
   *  The QFact is already saved at this point, so the host just clears
   *  its `show` flag and tears down. */
  @Output() closed = new EventEmitter<void>();

  /** Final on-screen position. Computed from `anchor` once we know our
   *  own dimensions so the popup hugs the highlight without overflowing. */
  position = signal<{ left: number; top: number }>({ left: 0, top: 0 });

  bUseHighlightedText: boolean = false;
  cNote: string = '';
  /** True for ~2s after a successful auto-save so the "✔ Saved"
   *  indicator appears briefly without staying on screen. */
  showSavedHint = signal<boolean>(false);
  /** Last note value successfully sent to the backend. Used to skip
   *  redundant saves on repeated blur events with the same content. */
  private lastSavedNote = '';
  private savedHintTimer: ReturnType<typeof setTimeout> | null = null;
  /** Tracks an in-flight saveNoteFn call so cancel() can await it
   *  before tearing down the popup. Without this, clicking outside
   *  would unmount the popup before the save resolved and the user
   *  would never see the "✔ Saved" confirmation. */
  private inflightSave: Promise<boolean> | null = null;
  /** Set true when cancel() has begun the close sequence so a second
   *  click / Escape during the saved-hint hold-time doesn't kick off
   *  a duplicate close. */
  private isClosing = false;

  @ViewChild('popupRoot', { static: true }) popupRoot!: ElementRef<HTMLDivElement>;
  @ViewChild('noteInput', { static: true }) noteInput!: ElementRef<HTMLTextAreaElement>;

  // OnPush + signals normally auto-schedule CD, but inside the async
  // cancel() flow (await save → setTimeout) the saved-hint signal
  // change can land between scheduled CD ticks, leaving the chip
  // unrendered before unmount. Inject CD ref so we can force a
  // synchronous render after flashSavedHint() and guarantee the
  // chip is in the DOM before the 900 ms hold begins.
  private readonly cdr = inject(ChangeDetectorRef);

  ngOnInit(): void {
    if (this.includeText) {
      this.bUseHighlightedText = true;
      this.cNote = this.highlightText || '';
    }
    // Defer placement to next frame so the host has its real width/height
    // (templateUrl+scss aren't applied yet during the synchronous init).
    requestAnimationFrame(() => {
      this.placeNearAnchor();
      // Auto-focus the textarea so the user can start typing immediately
      // — per the spec, the cursor should already be in the field. Place
      // the caret at the end so any pre-seeded "Use highlighted text"
      // content is still editable in the natural way.
      const ta = this.noteInput?.nativeElement;
      if (ta) {
        ta.focus({ preventScroll: true });
        const len = ta.value?.length ?? 0;
        try { ta.setSelectionRange(len, len); } catch { /* IE-style guard */ }
      }
    });
  }

  ngOnDestroy(): void {
    if (this.savedHintTimer) clearTimeout(this.savedHintTimer);
  }

  onUseHighlightedTextChange(checked: boolean): void {
    this.bUseHighlightedText = checked;
    if (checked) {
      // Seed only when empty so we don't clobber edits the user already
      // made. They can clear and re-tick to reset.
      if (!this.cNote?.trim()) this.cNote = this.highlightText || '';
    } else {
      // Untick → clear the auto-populated highlight text so the user
      // can dismiss without saving a note. Preserve anything they've
      // typed themselves (only clear when the field still matches the
      // exact highlight we seeded).
      if ((this.cNote || '') === (this.highlightText || '')) {
        this.cNote = '';
      }
    }
  }

  /** Auto-save on blur — the spec requires no explicit Save button.
   *  Skips the request when the note is empty (per "If user does not
   *  type anything, no note is saved.") or unchanged since the last
   *  successful save. Surfaces the result via the "✔ Saved" hint. */
  async onNoteBlur(): Promise<void> {
    await this.saveNoteIfDirty();
  }

  /** Shared helper used by both blur and cancel paths. Returns true
   *  when a save was actually issued (so cancel() knows to hold the
   *  popup open briefly for the "✔ Saved" confirmation). Idempotent —
   *  if the value is unchanged or empty, it's a no-op. */
  private async saveNoteIfDirty(): Promise<boolean> {
    const note = (this.cNote || '').trim();
    if (!note) return false;
    if (note === this.lastSavedNote) return false;
    if (!this.saveNoteFn) return false;
    if (this.inflightSave) {
      // Already saving the same dirty value — let the existing call
      // complete instead of firing a second request.
      return this.inflightSave;
    }
    const run = (async () => {
      try {
        const result = await this.saveNoteFn({
          note,
          useHighlightedText: this.bUseHighlightedText,
        });
        if (result?.ok) {
          this.lastSavedNote = note;
          this.flashSavedHint();
          return true;
        }
        return false;
      } catch {
        // silent — UX brief says "no disruptive messages"
        return false;
      }
    })();
    this.inflightSave = run;
    try {
      return await run;
    } finally {
      this.inflightSave = null;
    }
  }

  private flashSavedHint(): void {
    this.showSavedHint.set(true);
    if (this.savedHintTimer) clearTimeout(this.savedHintTimer);
    this.savedHintTimer = setTimeout(() => {
      this.showSavedHint.set(false);
      this.savedHintTimer = null;
    }, 2200);
  }

  /** Compute the popup's final {left, top} position from the anchor.
   *  Honours the anchor's `side` flag:
   *    - `side: 'right'` (default) → popup's LEFT edge sits at anchor.x
   *    - `side: 'left'`            → popup's RIGHT edge sits at anchor.x
   *      (so the popup grows leftwards from the anchor, putting it on
   *      the **left** side of the highlight — used when the highlight
   *      is on the right page in double-page mode and we want the
   *      popup in the gap between the two pages).
   *
   *  Vertical: centred on anchor.y with a TOOLBAR_GAP top clamp and a
   *  bottom clamp against the viewport. Horizontal: clamped to the
   *  viewport in both directions so the popup never escapes off-screen
   *  on narrow layouts. */
  private placeNearAnchor(): void {
    const el = this.popupRoot?.nativeElement;
    if (!el) return;
    const PAD = 8;
    // Reserve space for the top toolbar (case header + document tabs ≈
    // 100px). The popup is `position: fixed`, so we have to enforce
    // this clearance manually — otherwise short selections at the top
    // of the page anchor the popup right against the toolbar and the
    // header bar visually overlaps the popup's blue title bar.
    const TOOLBAR_GAP = 110;
    const w = el.offsetWidth;
    const h = el.offsetHeight;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const side = this.anchor.side ?? 'right';

    // Resolve `left` based on which side of the anchor the popup
    // should grow from.
    let left = side === 'left' ? this.anchor.x - w : this.anchor.x;
    let top = this.anchor.y - h / 2;

    // Clamp into the viewport in BOTH directions. We don't flip sides
    // mid-clamp — once the host says "this side", we honour it and
    // just clip against the edges so the popup never escapes off-screen.
    const maxLeft = Math.max(PAD, vw - w - PAD);
    if (left > maxLeft) left = maxLeft;
    if (left < PAD) left = PAD;
    if (top + h + PAD > vh) top = vh - h - PAD;
    if (top < TOOLBAR_GAP) top = TOOLBAR_GAP;

    this.position.set({ left, top });
  }

  @HostListener('window:resize')
  onWindowResize(): void {
    this.placeNearAnchor();
  }

  /** Escape closes the popup. The QFact is already saved, so this is
   *  purely a UI dismissal. Click-outside is handled by the backdrop
   *  template — we stop click propagation on the popup itself. */
  @HostListener('document:keydown.escape')
  onEscape(): void {
    void this.cancel();
  }

  /** Close sequence:
   *   1. Flush any unsaved note via saveNoteIfDirty(). When the user
   *      clicks the backdrop / Escape, the textarea blur may not fire
   *      first (Escape) or may race the close, so we run the save
   *      explicitly here as well — the helper is idempotent.
   *   2. Show the "✔ Saved" indicator on close if EITHER we just
   *      saved a dirty note now, OR a previous blur in this popup
   *      session already saved one. Without (b), a user who typed a
   *      note → blurred (auto-save fired, hint flashed and faded) →
   *      clicked the backdrop would see the popup close instantly
   *      with no visible confirmation, because saveNoteIfDirty
   *      short-circuits when the textarea value is unchanged.
   *      Per UX brief: "If a note is entered, show subtle ✔ Saved
   *      indicator within the pop-up."
   *   3. Hold the popup open ~900 ms so the hint is visible.
   *   4. Emit `closed` so the host unmounts. */
  async cancel(): Promise<void> {
    if (this.isClosing) return;
    this.isClosing = true;
    let didSave = false;
    try {
      didSave = await this.saveNoteIfDirty();
    } catch { /* swallowed in saveNoteIfDirty */ }
    const noteWasSaved = didSave || !!(this.lastSavedNote || '').trim();
    if (noteWasSaved) {
      // Re-flash so the hint is fresh on close even when the blur
      // already fired the save and the previous flash has faded.
      this.flashSavedHint();
      // Force CD so the chip is committed to the DOM BEFORE the 900 ms
      // hold begins — without this the OnPush component can lose the
      // signal-driven render in the async gap and the user would see
      // the popup unmount with no visible confirmation.
      this.cdr.detectChanges();
      // Brief hold so the saved-hint pill is visible before unmount.
      // Shorter than the full 2.2 s flash — just enough for the user
      // to register the confirmation.
      await new Promise(resolve => setTimeout(resolve, 900));
    }
    this.closed.emit();
  }
}
